const dateKey=date=>`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;
const localDate=key=>{const[y,m,d]=key.split('-').map(Number);return new Date(y,m-1,d,12);};
class Resource extends Base {
 mount(){this._value??={start:null,end:null};this.today=dateKey(new Date());this.month=localDate(this._value.start||this.today);this.month.setDate(1);this.focused=this._value.start||this.today;this.instanceId=uid();this.render(`<section class="launch panel"><span class="label">TIME, WITH A LITTLE INTENTION</span><h2>Make room in the calendar.</h2><p class="hint">A beginning, an ending, and a little space between.</p><button class="trigger secondary" aria-haspopup="dialog" aria-expanded="false"><span>▦</span><span data-value>Choose a date range</span><span>⌄</span></button><div class="summary"><span class="label">YOUR WINDOW</span><p data-summary>No dates selected.</p></div></section><dialog aria-labelledby="${this.instanceId}"><header class="row between"><h3 id="${this.instanceId}">Choose your window.</h3><button class="close" aria-label="Close calendar">×</button></header><div class="calendar-body"><div class="calendar"><div class="month-nav row between"><button class="icon" data-prev aria-label="Previous month">←</button><h4 aria-live="polite"></h4><button class="icon" data-next aria-label="Next month">→</button></div><div class="weekdays" role="row"></div><div class="days" role="grid" aria-label="Calendar days"></div></div><aside><span class="label">YOUR RANGE</span><div><small>FROM</small><strong data-from>—</strong></div><div><small>TO</small><strong data-to>—</strong></div><p class="hint" data-duration>Select a start and end date.</p></aside></div><footer class="row between"><button class="secondary" data-clear>Clear selection</button><button class="primary" data-apply disabled>Apply range ↗</button></footer></dialog>`,`.launch{min-height:450px;padding:42px;background:var(--bg);display:flex;flex-direction:column;justify-content:center;align-items:flex-start}h2{font:400 clamp(29px,5vw,43px) Georgia;letter-spacing:-1.4px;max-width:360px;margin:16px 0}.trigger{display:flex;align-items:center;gap:17px;margin:27px 0;padding:14px 16px;min-width:290px;background:var(--panel)}.trigger [data-value]{flex:1;text-align:left;font-size:12px}.trigger>span:first-child{color:var(--accent);font-size:20px}.summary{padding-top:20px;border-top:1px solid var(--line);width:100%}.summary p{font-size:13px;color:var(--muted);margin-top:10px}dialog{width:590px}header h3{font-size:15px;font-weight:500}.calendar-body{display:grid;grid-template-columns:1.8fr 1fr}.calendar{padding:18px}.month-nav h4{font-size:13px;font-weight:500;margin:0}.weekdays,.days .week{display:grid;grid-template-columns:repeat(7,1fr);gap:2px}.weekdays{margin:17px 0 8px;font-size:9px;color:var(--muted);text-align:center}.days button,.days .blank{min-height:39px;padding:7px 0;text-align:center;border:1px solid transparent;background:none;font-size:11px;border-radius:5px}.days button:hover{border-color:var(--accent)}.days button[data-between=true]{background:#c6e6b011}.days button[aria-selected=true]{background:var(--accent);color:#203425}.days button[data-today=true]:not([aria-selected=true]){border-bottom-color:var(--accent)}aside{border-left:1px solid var(--line);padding:27px 22px;background:#ffffff02}aside>div{margin-top:25px}aside small{display:block;font-size:8px;letter-spacing:1px;color:var(--muted)}aside strong{display:block;font-size:12px;font-weight:500;margin-top:9px}aside p{margin-top:27px;font-size:10px}footer{padding:17px 20px;border-top:1px solid var(--line)}footer button{font-size:11px}@media(max-width:540px){.launch{padding:30px 23px}.trigger{min-width:0;width:100%}.calendar-body{grid-template-columns:1fr}aside{display:none}.calendar{padding:15px}.days button{min-height:42px}.month-nav h4{font-size:12px}footer{padding:14px;gap:12px}footer button{font-size:10px}}`);this.setupDialog(this.$('dialog'),this.$('.trigger'));this.listen(this.$('.trigger'),'click',()=>this.open());this.listen(this.$('.close'),'click',()=>this.$('dialog').close());this.listen(this.$('dialog'),'close',()=>this.$('.trigger').setAttribute('aria-expanded','false'));this.listen(this.$('[data-prev]'),'click',()=>this.changeMonth(-1));this.listen(this.$('[data-next]'),'click',()=>this.changeMonth(1));this.listen(this.$('.days'),'click',e=>{const button=e.target.closest('[data-date]');if(button)this.choose(button.dataset.date);});this.listen(this.$('.days'),'keydown',e=>this.key(e));this.listen(this.$('[data-apply]'),'click',()=>{this.value={...this.draft};this.$('dialog').close();});this.listen(this.$('[data-clear]'),'click',()=>{this.value={start:null,end:null};this.$('dialog').close();});this.paintValue();}
 get value(){return{...this._value};}
 set value(value){const valid=key=>typeof key==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(key)&&dateKey(localDate(key))===key;this._value={start:valid(value?.start)?value.start:null,end:valid(value?.end)?value.end:null};if(this._value.start&&this._value.end&&this._value.end<this._value.start)[this._value.start,this._value.end]=[this._value.end,this._value.start];if(this._connected){this.paintValue();this.emit('range-change',this.value);}}
 open(){if(!this.$('dialog').open){this.dialogTrigger=this.$('.trigger');this.$('dialog').showModal();}this.draft={...this._value};this.focused=this._value.start||this.today;this.month=localDate(this.focused);this.month.setDate(1);this.draw();this.$('.trigger').setAttribute('aria-expanded','true');queueMicrotask(()=>this.$(`[data-date="${this.focused}"]`)?.focus());}
 paintValue(){const format=key=>key?new Intl.DateTimeFormat(undefined,{month:'short',day:'numeric',year:'numeric'}).format(localDate(key)):'—';const text=this._value.start&&this._value.end?`${format(this._value.start)} — ${format(this._value.end)}`:'Choose a date range';this.$('[data-value]').textContent=text;this.$('[data-summary]').textContent=this._value.start&&this._value.end?'A little time, set aside.':'No dates selected.';}
 draw(){const year=this.month.getFullYear(),month=this.month.getMonth(),start=this.text('week-start','monday')==='sunday'?0:1;this.$('h4').textContent=new Intl.DateTimeFormat(undefined,{month:'long',year:'numeric'}).format(this.month);const weekdays=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];this.$('.weekdays').innerHTML=Array.from({length:7},(_,i)=>`<span role="columnheader">${weekdays[(start+i)%7]}</span>`).join('');const offset=(new Date(year,month,1).getDay()-start+7)%7,count=new Date(year,month+1,0).getDate(),cells=Array.from({length:Math.ceil((count+offset)/7)*7},(_,i)=>{const day=i-offset+1;if(day<1||day>count)return'<span class="blank" role="gridcell"></span>';const date=dateKey(new Date(year,month,day,12));const selected=date===this.draft.start||date===this.draft.end,between=this.draft.start&&this.draft.end&&date>this.draft.start&&date<this.draft.end;const disabled=(this.getAttribute('min')&&date<this.getAttribute('min'))||(this.getAttribute('max')&&date>this.getAttribute('max'));return`<button role="gridcell" data-date="${date}" data-today="${date===this.today}" data-between="${Boolean(between)}" aria-selected="${selected}" tabindex="${date===this.focused?0:-1}" aria-label="${escape(new Intl.DateTimeFormat(undefined,{weekday:'long',month:'long',day:'numeric',year:'numeric'}).format(localDate(date)))}" ${disabled?'disabled':''}>${day}</button>`;});let rows='';for(let i=0;i<cells.length;i+=7)rows+=`<div class="week" role="row">${cells.slice(i,i+7).join('')}</div>`;this.$('.days').innerHTML=rows;this.$('.days').setAttribute('aria-label',this.$('h4').textContent);const fmt=key=>key?new Intl.DateTimeFormat(undefined,{month:'short',day:'numeric'}).format(localDate(key)):'—';this.$('[data-from]').textContent=fmt(this.draft.start);this.$('[data-to]').textContent=fmt(this.draft.end);this.$('[data-duration]').textContent=this.draft.start&&this.draft.end?`${Math.round((localDate(this.draft.end)-localDate(this.draft.start))/86400000)+1} days, including both ends.`:'Select a start and end date.';this.$('[data-apply]').disabled=!(this.draft.start&&this.draft.end);}
 choose(date){if(!this.draft.start||this.draft.end)this.draft={start:date,end:null};else if(date<this.draft.start)this.draft={start:date,end:this.draft.start};else this.draft.end=date;this.focused=date;this.draw();this.$(`[data-date="${date}"]`)?.focus();}
 changeMonth(delta){this.month.setMonth(this.month.getMonth()+delta);this.focused=dateKey(this.month);this.draw();}
 key(event){const button=event.target.closest('[data-date]');if(!button)return;const key=event.key;if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Home','End','PageUp','PageDown'].includes(key))return;event.preventDefault();let date=localDate(button.dataset.date);const first=this.text('week-start','monday')==='sunday'?0:1;if(key.startsWith('Arrow'))date.setDate(date.getDate()+({ArrowLeft:-1,ArrowRight:1,ArrowUp:-7,ArrowDown:7}[key]));else if(key==='Home'||key==='End')date.setDate(date.getDate()-(date.getDay()-first+7)%7+(key==='End'?6:0));else{const day=date.getDate();date.setDate(1);date.setMonth(date.getMonth()+(key==='PageDown'?1:-1)*(event.shiftKey?12:1));date.setDate(Math.min(day,new Date(date.getFullYear(),date.getMonth()+1,0).getDate()));}let target=dateKey(date);if(this.getAttribute('min')&&target<this.getAttribute('min'))target=this.getAttribute('min');if(this.getAttribute('max')&&target>this.getAttribute('max'))target=this.getAttribute('max');this.focused=target;this.month=localDate(target);this.month.setDate(1);this.draw();this.$(`[data-date="${target}"]`)?.focus();}
 configured(name){if(name==='week-start'&&this.$('dialog').open)this.draw();}
 teardown(){this.$('dialog')?.close();}
}
